        f_run[k]<=c_age_f[32*k+:32]==p_run_f[32*k+:32];f_writer[k]<=c_age_f[32*k+:32]==p_writer_f[32*k+:32];
        f_link[k]<=c_age_f[32*k+:32]==p_link_f[32*k+:32];f_quiet[k]<=c_age_f[32*k+:32]==p_quiet_f[32*k+:32];
