  always @(posedge ck or negedge rn)if(!rn)begin tc<=0;ag<=0;cnt<=0;end else begin tc<=tnx;ag<=anx;cnt<=cnx;end
  assign meta_f[68*gk+:68]=meta;assign ag1_f[32*gk+:32]=ag1;assign tc1_f[32*gk+:32]=tc1;
