 always @(posedge ck or negedge rn)if(!rn)begin om<=0;oag<=0;otc<=0;om_e_ep<=0;om_e_ct<=0;end else begin om<=omx;oag<=oax;otc<=otx;om_e_ep<=omx[0+:16];om_e_ct<=omx[52+:14];end
